import os
import json
import re
from datetime import datetime

GESTALTS_DIR = "/mnt/data/vault/gestalts"
MANIFEST_PATH = "/mnt/data/vault/index/manifest.json"

def extract_metadata(file_path):
    metadata = {
        "path": file_path,
        "title": None,
        "date": None,
        "tier": None,
        "tags": []
    }

    filename = os.path.basename(file_path)
    date_match = re.match(r"(\d{4}-\d{2}-\d{2})", filename)
    if date_match:
        metadata["date"] = date_match.group(1)

    with open(file_path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    for line in lines:
        if line.lower().startswith("title:"):
            metadata["title"] = line.split(":", 1)[1].strip()
        elif line.lower().startswith("tier:"):
            try:
                metadata["tier"] = int(line.split(":", 1)[1].strip())
            except ValueError:
                pass
        elif line.lower().startswith("tags:"):
            tag_line = line.split(":", 1)[1].strip()
            tags = [tag.strip().lower() for tag in tag_line.split(",")]
            metadata["tags"] = tags
        elif line.strip().startswith("#") and not metadata["title"]:
            metadata["title"] = line.strip("# ").strip()

        if metadata["title"] and metadata["tier"] is not None and metadata["tags"]:
            break

    return metadata

manifest = []
if os.path.exists(GESTALTS_DIR):
    for fname in os.listdir(GESTALTS_DIR):
        fpath = os.path.join(GESTALTS_DIR, fname)
        if fname.endswith(".md"):
            meta = extract_metadata(fpath)
            manifest.append(meta)

# Show as a DataFrame for inspection
import pandas as pd
import ace_tools as tools; tools.display_dataframe_to_user(name="Generated Manifest", dataframe=pd.DataFrame(manifest))

