def is_idea(text: str) -> List[str]:
    """Return True if the text matches any of the idea patterns."""
    text = text.lower()
    return [pat for pat in IDEA_PATTERNS if re.search(pat, text)]

def extract_ideas(messages: List[Dict[str, str]]) -> Dict:
    """
    Extract design-relevant messages from a list of chat messages.
    Each message should be a dict with 'role' and 'content'.
    Focuses on AI Partner messages.
    """
    ideas = {}
    for msg in messages:
        if msg["role"] == "assistant":
            result = is_idea(msg["flattened"])
            if len(result) > 0:
                idea = msg.copy()
                idea["idea_patterns"] = result
                ideas[msg["id"]] = idea
    return ideas

